<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script><script>const moneyLabel=value=>`Rp ${new Intl.NumberFormat('id-ID',{notation:'compact'}).format(value)}`;new Chart(document.getElementById('financial-chart'),{type:'line',data:{labels:@json($financialChart->pluck('label')),datasets:[{label:'Pendapatan',data:@json($financialChart->pluck('revenue')),borderColor:'#3e67f6',backgroundColor:'rgba(62,103,246,.12)',fill:true,tension:.35},{label:'Modal',data:@json($financialChart->pluck('capital')),borderColor:'#f1416c',backgroundColor:'rgba(241,65,108,.08)',fill:true,tension:.35},{label:'Keuntungan',data:@json($financialChart->pluck('profit')),borderColor:'#50cd89',backgroundColor:'rgba(80,205,137,.08)',fill:true,tension:.35}]},options:{responsive:true,interaction:{mode:'index',intersect:false},scales:{y:{beginAtZero:true,ticks:{callback:moneyLabel}}},plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:context=>`${context.dataset.label}: ${moneyLabel(context.raw)}`}}}}});new Chart(document.getElementById('product-chart'),{type:'doughnut',data:{labels:@json($productChart->pluck('product_name')),datasets:[{data:@json($productChart->pluck('transaction_count')),backgroundColor:['#3e67f6','#50cd89','#f1416c','#f6c343','#8b5cf6'],borderColor:'#fff',borderWidth:4,hoverOffset:8}]},options:{responsive:true,maintainAspectRatio:false,cutout:'68%',plugins:{legend:{position:'bottom',labels:{usePointStyle:true,padding:18}},tooltip:{callbacks:{label:context=>`${context.label}: ${context.raw} transaksi`}}}}});</script>
